#!/usr/bin/env python3
"""Render a Claude Code session transcript (.jsonl) to a PDF, unedited.

Every user message, assistant message, tool call and tool result is printed
in order, verbatim. Only Claude Code's bookkeeping fields (ids, timestamps
other than the one shown, token counts) are left out; no message text is
changed, summarised or removed.

Usage: python3 -I transcript_to_pdf.py <session.jsonl> <out.pdf> [title]
Needs Google Chrome (used headless to print the HTML to PDF).
"""
import html
import json
import subprocess
import sys
import tempfile
from pathlib import Path

CHROME = "/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"


def block_html(block):
    kind = block.get("type")
    if kind == "text":
        return f'<pre class="text">{html.escape(block.get("text", ""))}</pre>'
    if kind == "thinking":
        return f'<pre class="think">[thinking]\n{html.escape(block.get("thinking", ""))}</pre>'
    if kind == "tool_use":
        body = json.dumps(block.get("input", {}), indent=2, ensure_ascii=False)
        return f'<pre class="tool">[tool call: {html.escape(block.get("name", ""))}]\n{html.escape(body)}</pre>'
    if kind == "tool_result":
        content = block.get("content", "")
        if isinstance(content, list):
            parts = []
            for c in content:
                if c.get("type") == "text":
                    parts.append(c.get("text", ""))
                else:
                    parts.append(f"[{c.get('type', 'non-text')} content]")
            content = "\n".join(parts)
        return f'<pre class="result">[tool result]\n{html.escape(str(content))}</pre>'
    if kind == "image":
        return '<pre class="result">[image attached]</pre>'
    return f'<pre class="result">[{html.escape(str(kind))}]\n{html.escape(json.dumps(block, ensure_ascii=False)[:20000])}</pre>'


def entry_html(entry):
    kind = entry.get("type")
    if kind not in ("user", "assistant"):
        return ""
    msg = entry.get("message") or {}
    role = msg.get("role", kind)
    stamp = entry.get("timestamp", "")
    content = msg.get("content", "")
    if isinstance(content, str):
        inner = f'<pre class="text">{html.escape(content)}</pre>'
    else:
        inner = "".join(block_html(b) for b in content)
    return f'<div class="msg {html.escape(role)}"><div class="hdr">{html.escape(role.upper())} · {html.escape(stamp)}</div>{inner}</div>'


def main():
    src, out = Path(sys.argv[1]), Path(sys.argv[2])
    title = sys.argv[3] if len(sys.argv) > 3 else src.stem
    rows = []
    with src.open(encoding="utf-8") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                rows.append(entry_html(json.loads(line)))
            except json.JSONDecodeError:
                rows.append(f'<pre class="result">[unparseable line]\n{html.escape(line[:2000])}</pre>')
    doc = f"""<!doctype html><html><head><meta charset="utf-8"><title>{html.escape(title)}</title>
