const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, LevelFormat, AlignmentType,
} = require("docx");

const P = (text, opts = {}) => new Paragraph({ spacing: { after: 140, line: 300 }, ...opts, children: runs(text) });
const B = (text) => new Paragraph({ numbering: { reference: "bullets", level: 0 }, spacing: { after: 80, line: 290 }, children: runs(text) });
const H1 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_1, spacing: { before: 320, after: 140 }, children: [new TextRun(text)] });
const H2 = (text) => new Paragraph({ heading: HeadingLevel.HEADING_2, spacing: { before: 260, after: 120 }, children: [new TextRun(text)] });

// **bold** and `code` inline markup
function runs(text) {
  const out = [];
  const re = /(\*\*[^*]+\*\*|`[^`]+`)/g;
  let last = 0, m;
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(new TextRun(text.slice(last, m.index)));
    const t = m[0];
    if (t.startsWith("**")) out.push(new TextRun({ text: t.slice(2, -2), bold: true }));
    else out.push(new TextRun({ text: t.slice(1, -1), font: "Menlo", size: 20 }));
    last = m.index + t.length;
  }
  if (last < text.length) out.push(new TextRun(text.slice(last)));
  return out;
}

const body = [
  new Paragraph({ heading: HeadingLevel.TITLE, spacing: { after: 120 }, children: [new TextRun("auto_experiment: project write-up")] }),
  P("An autonomous experiment platform for RL training, built with AI coding agents. This write-up covers the AI tools I used and how, followed by my answers to the five questions."),

  H1("The AI tools I used and how"),
  P("I never asked one assistant to \"build the app\". I set up a small hierarchy of AI agents, kept myself at the top as the decision-maker, and used review surfaces so that every important choice came back to me."),
  B("**Claude Code** (Anthropic's agentic coding CLI) is the engine underneath everything. Every agent below is a Claude Code session."),
  B("**Firstmate** is an open-source supervisor layer for Claude Code. My main session acted as a \"first mate\" that never edits project code itself: it writes instructions, launches worker agents in isolated git worktrees, supervises them, and brings decisions back to me. I gave this project its own persistent \"second mate\", so its work and records stayed separate from my other work."),
  B("**Herdr** is a terminal workspace for agents. Every worker agent ran in its own visible pane, so I could watch it or type into it. The system I built uses the same idea for its own experiment workers."),
  B("**Lavish editor** is a local review surface for agent-generated HTML. I used it to specify requirements and to review the architecture, accepting, rejecting or changing each item and sending structured answers back to the agent."),
  B("**no-mistakes** is an automated validation pipeline (review, tests, documentation, lint, PR) that the worker agent drove before opening the pull request. Its review and test agents found real bugs."),
  P("The working loop was: I state intent in plain language → the agent turns it into a structured board → I decide item by item → a worker builds in isolation → automated review checks it → I approve or redirect."),

  H1("1. What I did"),
  P("I built `auto_experiment`, a master–worker system that runs reinforcement-learning experiments on one machine. A deterministic Python master watches training telemetry while runs train, prunes runs that aren't earning their compute, decides what to run next, and reports to a local dashboard. Workers are Claude Code agents in Herdr panes: they execute the runs they are assigned, debug crashes, and never choose what to run."),
  P("I modelled the control plane on Firstmate's supervision pattern: a single master with an exclusive lock, durable per-worker inboxes, append-only status events, the master reading and typing into worker panes, and human input in a pane always overriding the master. Karpathy's autoresearch and Hugging Face's ML Intern shaped the goal of a system that decides its own next experiment; I took ideas from them, not code."),

  H1("2. Clarity of the project"),
  P("I deliberately didn't start with code. When the first plan was a \"thin working slice\", I stopped it and asked for requirements first, as a review board in Lavish. I went through 13 requirements drawn from my own description and accepted, rejected or changed each one."),
  P("The most important change was to how the system splits deciding from executing. The draft said each worker runs one experiment in its own pane. I changed that: the master is the brain that decides which experiments to run and how to interpret them, workers only execute, and one pane can run several configurations programmatically."),
  P("I then pinned down the constraints:"),
  B("This Mac only (Apple M1, CPU), at most 2 concurrent workers."),
  B("Telemetry in our own JSONL files: return, losses, entropy, KL, gradient norms, system load, crashes."),
  B("Every experiment keyed by a run ID; locks so there is only one master and no run or device is ever driven twice; full crash recovery from disk."),
  B("Pruning that is config- and budget-driven: successive halving / ASHA, plateau and divergence rules, and optional LLM judgement over the curves."),
  B("Autonomy limits: the master may launch, prune and fork runs on its own, but must ask before changing training code or exceeding a budget."),
  B("A concrete first milestone: the master runs 4 CartPole configurations end to end."),

