#!/usr/bin/env python3
"""Sanitize Claude Code .jsonl transcripts for public release.

One output line per input line (line numbers are preserved). Each JSON record
is parsed, every string is cleaned, and the record is re-serialized.
Usage: python3 -I sanitize.py <in.jsonl> <out.jsonl>  (prints removal counts)
"""
import json
import re
import sys
from collections import Counter

COUNTS = Counter()

SUBS = [
    (re.compile(r"[A-Za-z0-9._%+-]+@[REDACTED_ORG]\.com", re.I), "[REDACTED_EMAIL]", "email"),
    (re.compile(r"hyp(?:er|r)bots", re.I), "[REDACTED_ORG]", "employer name"),
    (re.compile(r"sk-ant-[A-Za-z0-9_-]{16,}"), "[REDACTED_SECRET]", "secret"),
    (re.compile(r"ghp_[A-Za-z0-9]{30,}"), "[REDACTED_SECRET]", "secret"),
    (re.compile(r"AKIA[0-9A-Z]{16}"), "[REDACTED_SECRET]", "secret"),
    (re.compile(r"~\b"), "~", "local home path"),
    (re.compile(r"-Users-USER-"), "-Users-USER-", "local home path"),
[line removed: unrelated private work]
]

# A line inside any text that mentions unrelated private work is replaced whole.
DROP = re.compile(
[line removed: unrelated private work]
    r"\bgmf\b|generali[sz]ed[-_ ]matching|matching[-_ ](?:observability|framework|bug|generali|engine|work|change|corpus|trace|seam|snapshot|input|outbox|overview|exception|series|duplicate|frozen|published|retired|what)|"
[line removed: unrelated private work]
    re.I,
)
DROP_MARK = "[line removed: unrelated private work]"


def clean_text(s: str) -> str:
    if DROP.search(s):
        lines = s.split("\n")
        kept = []
        for ln in lines:
            if DROP.search(ln):
                COUNTS["lines about unrelated private work"] += 1
                if not kept or kept[-1] != DROP_MARK:
                    kept.append(DROP_MARK)
            else:
                kept.append(ln)
        s = "\n".join(kept)
    for rx, rep, label in SUBS:
        s, n = rx.subn(rep, s)
        COUNTS[label] += n
    return s


def walk(node):
    if isinstance(node, dict):
        if node.get("type") == "image" and isinstance(node.get("source"), dict):
            COUNTS["embedded images"] += 1
            return {"type": "text", "text": "[image removed: screenshot pasted by the user]"}
        return {k: (v if k == "signature" else walk(v)) for k, v in node.items()}
    if isinstance(node, list):
        return [walk(v) for v in node]
    if isinstance(node, str):
        return clean_text(node)
    return node


def main():
    src, dst = sys.argv[1], sys.argv[2]
    with open(src, encoding="utf-8") as fin, open(dst, "w", encoding="utf-8") as fout:
        for line in fin:
            raw = line.rstrip("\n")
            if not raw.strip():
                fout.write("\n")
                continue
            try:
                rec = json.loads(raw)
            except json.JSONDecodeError:
                COUNTS["unparseable records replaced"] += 1
                fout.write(json.dumps({"type": "redacted", "note": "unparseable record removed"}) + "\n")
                continue
            fout.write(json.dumps(walk(rec), ensure_ascii=False, separators=(",", ":")) + "\n")
    print(json.dumps(dict(COUNTS)))


if __name__ == "__main__":
    main()

